sparql_tries.sparql:
SELECT DISTINCT (STR(?year) AS ?modelYear) WHERE {
  ?camp rc:campaignNumber "26V430000" ;
        rc:affects ?variant .
  ?variant rc:ofModel ?model ;
           rc:modelYear ?year .
  ?model rc:name "TELLURIDE" ;
         rc:ofMake ?make .
  ?make rc:name "KIA" .
}
ORDER BY ?modelYear

SELECT DISTINCT ?categoryName WHERE {
  ?campaign rc:campaignNumber "10V388000" ;
            rc:affectsComponent ?comp .
  ?comp skos:broader* ?top .
  FILTER NOT EXISTS { ?top skos:broader ?higher . }
  ?top rc:name ?categoryName .
}
ORDER BY ?categoryName

SELECT DISTINCT ?campaignNumber ?makeName WHERE {
  ?c a rc:RecallCampaign ;
     rc:doNotDrive true ;
     rc:campaignNumber ?campaignNumber ;
     rc:affects ?v .
  ?v rc:ofModel ?m .
  ?m rc:ofMake ?make .
  ?make rc:name ?makeName .
  FILTER (UCASE(STR(?makeName)) IN ("HYUNDAI", "KIA", "GENESIS"))
}
ORDER BY ?makeName ?campaignNumber

SELECT ?campaignNumber WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:campaignNumber ?campaignNumber ;
            rc:initiatedBy ?initiatedBy .
  FILTER(CONTAINS(UCASE(STR(?initiatedBy)), "OVSC"))
}
ORDER BY ?campaignNumber
